const fs=require("node:fs");
const d=JSON.parse(fs.readFileSync(process.argv[1],"utf8"));
const groups={
objective:["objectives","objective_id"],process:["processes","process_id"],step:["steps","step_id"],risk:["risks","risk_id"],control_objective:["control_objectives","control_objective_id"],control:["controls","control_id"],observation:["control_observations","control_observation_id"],baseline:["baseline_links","baseline_link_id"],comparison:["comparisons","comparison_id"],gap:["gaps","gap_id"],recommendation:["recommendations","recommendation_id"],action:["actions","action_id"],scenario:["no_change_scenarios","no_change_scenario_id"],source:["source_register","source_id"],opportunity:["design_opportunities","design_opportunity_id"],test:["test_attributes","test_attribute_id"],metric:["metric_proposals","metric_id"],dependency:["dependencies","dependency_id"],rcm:["rcm_relationships","rcm_id"],relationship:["relationships","relationship_id"]
};
const index={};
const errors=[];
for(const [kind,[key,id]] of Object.entries(groups)){index[kind]=new Map();for(const x of d[key]){if(index[kind].has(x[id]))errors.push("Duplicate "+x[id]);index[kind].set(x[id],x);}}
function check(kind,id,context){if(id!=null&&!index[kind].has(id))errors.push(context+" unresolved "+kind+" "+id);}
for(const r of d.risks){for(const v of r.objective_ids)check("objective",v,r.risk_id);for(const v of r.process_ids)check("process",v,r.risk_id);for(const v of r.step_ids)check("step",v,r.risk_id);}
for(const c of d.controls){for(const v of c.observation_ids){check("observation",v,c.control_id);if(index.observation.get(v)?.control_id!==c.control_id)errors.push("Observation owner mismatch "+v);}for(const v of c.risk_ids)check("risk",v,c.control_id);for(const v of c.control_objective_ids)check("control_objective",v,c.control_id);}
for(const o of d.control_observations){check("control",o.control_id,o.control_observation_id);for(const v of o.source_ids)check("source",v,o.control_observation_id);for(const v of o.evidence_ids)check("source",v,o.control_observation_id);for(const v of o.process_ids)check("process",v,o.control_observation_id);for(const v of o.step_ids)check("step",v,o.control_observation_id);if(o.analysis_layer==="As-Performed"&&!o.evidence_ids.length)errors.push("Missing performed evidence "+o.control_observation_id);}
for(const c of d.comparisons){
for(const v of c.baseline_link_ids)check("baseline",v,c.comparison_id);
for(const v of c.logical_control_ids)check("control",v,c.comparison_id);
for(const [field,layer] of [["documented_observation_ids","As-Documented"],["designed_observation_ids","As-Designed"],["performed_observation_ids","As-Performed"],["target_observation_ids","Target-State"]])for(const id of c[field]){check("observation",id,c.comparison_id);const o=index.observation.get(id);if(o?.analysis_layer!==layer)errors.push("Layer mismatch "+c.comparison_id+" "+id);if(!c.logical_control_ids.includes(o?.control_id))errors.push("Comparison control mismatch "+id);}
for(const v of c.gap_ids)check("gap",v,c.comparison_id);
for(const v of c.recommendation_ids)check("recommendation",v,c.comparison_id);
for(const v of c.no_change_scenario_ids)check("scenario",v,c.comparison_id);
}
for(const r of d.rcm_relationships){
for(const [kind,key] of [["process","process_id"],["step","step_id"],["risk","risk_id"],["control_objective","control_objective_id"],["control","control_id"],["observation","control_observation_id"]])check(kind,r[key],r.rcm_id);
const o=index.observation.get(r.control_observation_id);
if(o?.control_id!==r.control_id||o?.analysis_layer!==r.analysis_layer)errors.push("RCM observation mismatch "+r.rcm_id);
if(r.process_id&&!o.process_ids.includes(r.process_id))errors.push("RCM process scope mismatch "+r.rcm_id);
if(r.step_id&&!o.step_ids.includes(r.step_id))errors.push("RCM step scope mismatch "+r.rcm_id);
for(const v of r.baseline_link_ids){check("baseline",v,r.rcm_id);if(!index.baseline.get(v).candidate_control_ids.includes(r.control_id))errors.push("RCM baseline control mismatch "+r.rcm_id);}
for(const v of r.comparison_ids){check("comparison",v,r.rcm_id);const c=index.comparison.get(v);if(!c.logical_control_ids.includes(r.control_id))errors.push("RCM comparison control mismatch "+r.rcm_id);for(const b of r.baseline_link_ids)if(!c.baseline_link_ids.includes(b))errors.push("RCM baseline missing in comparison "+r.rcm_id);}
}
const pairSet=new Set(d.rcm_relationships.map(x=>x.risk_id+"|"+x.control_id));
for(const c of d.controls)for(const r of c.risk_ids)if(!pairSet.has(r+"|"+c.control_id))errors.push("Missing RCM risk-control link "+r+" "+c.control_id);
for(const a of d.actions){check("recommendation",a.recommendation_id,a.action_id);for(const v of a.gap_ids)check("gap",v,a.action_id);for(const v of a.design_opportunity_ids||[])check("opportunity",v,a.action_id);for(const v of a.dependencies)check("action",v,a.action_id);for(const v of a.comparison_ids)check("comparison",v,a.action_id);for(const v of a.no_change_scenario_ids)check("scenario",v,a.action_id);if(a.owner!=="Not provided"||a.target_date!==null||a.budget!=="Not provided")errors.push("Unexpected assumed action facts "+a.action_id);}
for(const n of d.no_change_scenarios){if(n.horizon!==null)errors.push("Invented horizon "+n.no_change_scenario_id);for(const v of n.existing_protection.control_observation_ids){check("observation",v,n.no_change_scenario_id);if(index.observation.get(v)?.analysis_layer==="Target-State")errors.push("Target counted current "+v);}}
const all=new Set();for(const m of Object.values(index))for(const id of m.keys())all.add(id);
for(const r of d.relationships){if(!all.has(r.from_id))errors.push("Relationship from missing "+r.from_id);if(!all.has(r.to_id))errors.push("Relationship to missing "+r.to_id);}
const current=d.controls.filter(x=>x.lifecycle_scope!=="Target-State only").length;
if(current!==3||d.controls.filter(x=>x.control_id==="CTL-SHARED-19").length!==1)errors.push("Incorrect logical control count");
if(d.control_observations.some(x=>x.analysis_layer==="As-Designed"))errors.push("Invented As-Designed");
if(index.observation.get("OBS-19-PA").raw_status!=="VERIFIED"||index.observation.get("OBS-19-PB").raw_status!=="PENDING_REVIEW")errors.push("Raw status changed");
const report={validation_kind:"Deterministic JSON/ID/relationship checks only; no business approval, OE testing or independent professional review",errors,counts:{risks:d.risks.length,current_logical_controls:current,target_only_controls:d.controls.length-current,control_observations:d.control_observations.length,rcm_rows:d.rcm_relationships.length,actions:d.actions.length,risk_control_pairs:pairSet.size,relationships:d.relationships.length},preserved:{raw_statuses:true,as_designed_empty:true,action_owner_date_budget_unknown:true,no_target_in_existing_protection:true}};
console.log(JSON.stringify(report,null,2));
if(errors.length)process.exit(1);
